  dst: { ramBaseMB: 819, ramPerPlayerMB: 205, cpuBaseCores: 0.4, cpuPerPlayer: 0.1, diskBaseGB: 4, diskPerPlayerGB: 1, maxSeededSlots: 16 },
  vintagestory: { ramBaseMB: 0, ramPerPlayerMB: 256, cpuBaseCores: 0, cpuPerPlayer: 0.125, diskBaseGB: 0, diskPerPlayerGB: 1.25, maxSeededSlots: 16 },
  necesse: { ramBaseMB: 0, ramPerPlayerMB: 205, cpuBaseCores: 0.5, cpuPerPlayer: 0.1, diskBaseGB: 5, diskPerPlayerGB: 0.8, maxSeededSlots: 16 },
  tf2: { ramBaseMB: 0, ramPerPlayerMB: 128, cpuBaseCores: 1, cpuPerPlayer: 0.05, diskBaseGB: 10, diskPerPlayerGB: 1.25, maxSeededSlots: 32 },
  l4d2: { ramBaseMB: 0, ramPerPlayerMB: 256, cpuBaseCores: 1, cpuPerPlayer: 0.125, diskBaseGB: 10, diskPerPlayerGB: 1.25, maxSeededSlots: 16 },
  // ── Wave 8 (2026-08-31). ROUGH fits from each family's 3 seeded tiers in
