  nightingale: { ramBaseMB: 2048, ramPerPlayerMB: 700, cpuBaseCores: 1, cpuPerPlayer: 0.25, diskBaseGB: 15, diskPerPlayerGB: 1.9, maxSeededSlots: 8 },
