  kf2: { ramBaseMB: 819, ramPerPlayerMB: 205, cpuBaseCores: 1.5, cpuPerPlayer: 0.07, diskBaseGB: 12, diskPerPlayerGB: 0.83, maxSeededSlots: 24 },
  barotrauma: { ramBaseMB: 1024, ramPerPlayerMB: 190, cpuBaseCores: 0.5, cpuPerPlayer: 0.1, diskBaseGB: 5, diskPerPlayerGB: 0.94, maxSeededSlots: 16 },
  sandstorm: { ramBaseMB: 819, ramPerPlayerMB: 165, cpuBaseCores: 1.25, cpuPerPlayer: 0.07, diskBaseGB: 12, diskPerPlayerGB: 1.25, maxSeededSlots: 32 },
  // ── Wave 9 (2026-08-31). ROUGH fits from each family's 3 seeded tiers in
  //    prisma/seed-wave9-games.ts — same confidence caveat as the file header. ──
  mordhau: { ramBaseMB: 1832, ramPerPlayerMB: 101, cpuBaseCores: 0.89, cpuPerPlayer: 0.05, diskBaseGB: 9, diskPerPlayerGB: 0.49, maxSeededSlots: 64 },
  theisle: { ramBaseMB: 0, ramPerPlayerMB: 614, cpuBaseCores: 0, cpuPerPlayer: 0.15, diskBaseGB: 20, diskPerPlayerGB: 1.0, maxSeededSlots: 40 },
  stationeers: { ramBaseMB: 1317, ramPerPlayerMB: 658, cpuBaseCores: 1.29, cpuPerPlayer: 0.14, diskBaseGB: 13, diskPerPlayerGB: 1.61, maxSeededSlots: 10 },
  eco: { ramBaseMB: 0, ramPerPlayerMB: 658, cpuBaseCores: 0, cpuPerPlayer: 0.23, diskBaseGB: 5, diskPerPlayerGB: 1.61, maxSeededSlots: 24 },
  empyrion: { ramBaseMB: 0, ramPerPlayerMB: 1024, cpuBaseCores: 0, cpuPerPlayer: 0.38, diskBaseGB: 10, diskPerPlayerGB: 2.5, maxSeededSlots: 16 },
  // plutoniumt4: least-squares fit over this family's own 3 seeded tiers
  // (2GB/18, 4GB/32, 6GB/64 — prisma/seed-plutonium.ts) — a COD4-era engine is
