  plutoniumt4: { ramBaseMB: 877, ramPerPlayerMB: 85, cpuBaseCores: 1.44, cpuPerPlayer: 0.023, diskBaseGB: 9, diskPerPlayerGB: 0.33, maxSeededSlots: 64 },
