  // lib/game-config.ts's max_players field comment), differing only in RAM
  // headroom for DLC maps/AI traffic/mods, so there is no per-player RAM
  // variation to fit a slope against. Instead built from the SCS forum's own
  // real numbers (forum.scssoft.com/viewtopic.php?t=316296: idle ~180MB,
  // ~150MB with one player) plus headroom for Docker/OS overhead and AI
  // traffic — at 8 players this curve recommends ~1.3GB/1 core/~8GB disk,
  // landing inside the smallest seeded tier, which is the intended shape
  // ("never a hard floor" per this function's own doc comment above — a
  // customer who wants DLC maps or a heavy modlist should pick a bigger
  // tier directly, same as the tier picker already offers).
  ets2: { ramBaseMB: 384, ramPerPlayerMB: 110, cpuBaseCores: 0.5, cpuPerPlayer: 0.06, diskBaseGB: 4, diskPerPlayerGB: 0.5, maxSeededSlots: 8 },
  ats: { ramBaseMB: 384, ramPerPlayerMB: 110, cpuBaseCores: 0.5, cpuPerPlayer: 0.06, diskBaseGB: 4, diskPerPlayerGB: 0.5, maxSeededSlots: 8 },
  // dayz (Wave 11, 2026-09-24): least-squares fit over its own 3 seeded tiers
  // (6GB/20, 8GB/40, 12GB/60 — prisma/seed-wave11-dayz.ts). maxSeededSlots
  // matches DayZ's real official 60-player ceiling (lib/game-config.ts's
  // maxPlayers field), not an arbitrary largest-tier number.
  dayz: { ramBaseMB: 2731, ramPerPlayerMB: 153.6, cpuBaseCores: 1, cpuPerPlayer: 0.05, diskBaseGB: 10, diskPerPlayerGB: 0.5, maxSeededSlots: 60 },
  // fivem (feature-flagged, 2026-10-01): fitted to the PROPOSED tiers in
  // prisma/seed-fivem.ts (4GB/2vCPU/48, 8GB/4vCPU/128, 16GB/6vCPU/255). Real
  // FXServer usage is dominated by the customer's resources (an ESX/QBCore
  // stack with MySQL is far heavier than vanilla), so this is a floor.
  fivem: { ramBaseMB: 1300, ramPerPlayerMB: 58, cpuBaseCores: 1.1, cpuPerPlayer: 0.019, diskBaseGB: 18, diskPerPlayerGB: 0.24, maxSeededSlots: 255 },
};

/** Slider ceiling per family: 5x the largest tier actually sold today, floored at
 *  50 so even a small-roster game (e.g. The Forest, seeded up to 8) still offers a
 *  meaningfully bigger custom option. */
export function playerSliderMax(family: GameFamily): number {
  const c = GAME_PLAYER_CURVES[family];
  return Math.max(50, c.maxSeededSlots * 5);
}

/**
 * Recommended cpu/ram/disk for a given player count on this family — a
 * DEFAULT-SETTER for the custom-spec sliders, never a hard floor or ceiling
 * itself (the caller clamps into the actual custom-plan floor/ceiling).
 */
export function recommendedSpecForPlayers(family: GameFamily, players: number): GameResourceSpec {
  const c = GAME_PLAYER_CURVES[family];
  const p = Math.max(1, Math.round(players));
  const ramMB = Math.max(512, Math.round((c.ramBaseMB + c.ramPerPlayerMB * p) / 256) * 256);
  const cpuCores = Math.max(1, Math.round(c.cpuBaseCores + c.cpuPerPlayer * p));
  const diskGB = Math.max(5, Math.round(c.diskBaseGB + c.diskPerPlayerGB * p));
  return { cpuCores, ramMB, diskGB };
}
