 * used (UNVERIFIED, conservative). `off` is capped at 32 (the pre-OneSync
 * limit; UNVERIFIED primary wording, community-standard).
 *
 * This is a UX guard only: FXServer/Cfx enforce the real entitlement against
 * the key itself. The tier is self-declared by the customer — we cannot see
 * their Cfx account.
 */
const TIER_CAPS: Record<FivemLicenceTier, Record<FivemOneSync, number>> = {
  default: { on: 48, legacy: 32, off: 32 },
  argentum: { on: 64, legacy: 64, off: 32 },
  aurum: { on: 128, legacy: 64, off: 32 },
  platinum: { on: 2048, legacy: 128, off: 32 },
};

export function licenceSlotCap(tier: FivemLicenceTier, onesync: FivemOneSync): number {
  return (TIER_CAPS[tier] ?? TIER_CAPS.default)[onesync] ?? 32;
}

/** The effective sv_maxclients ceiling: the smaller of the plan's slots and the licence cap. */
export function effectiveSlotCap(planSlots: number | null | undefined, tier: FivemLicenceTier, onesync: FivemOneSync): number {
  const lic = licenceSlotCap(tier, onesync);
  const plan = Number.isFinite(planSlots) && (planSlots as number) > 0 ? (planSlots as number) : lic;
  return Math.max(1, Math.min(plan, lic, 2048));
}

/** Customer-facing reason sv_maxclients is too high, or null. */
export function slotCapError(maxClients: number, planSlots: number | null | undefined, tier: FivemLicenceTier, onesync: FivemOneSync): string | null {
  const cap = effectiveSlotCap(planSlots, tier, onesync);
  if (maxClients <= cap) return null;
  const lic = licenceSlotCap(tier, onesync);
  if (planSlots && planSlots < lic) return `Max players is limited to ${cap} on this plan. Pick a bigger plan for more slots.`;
  return `Your Cfx.re licence tier (${tier}, OneSync ${onesync}) allows up to ${lic} players. Upgrade your own Cfx.re subscription or lower Max players.`;
}

// ---------------------------------------------------------------------------
// Artifacts (official runtime.fivem.net, Linux "proot" builds)
// ---------------------------------------------------------------------------

export const FIVEM_CHANGELOG_URL = "https://changelogs-live.fivem.net/api/changelog/versions/linux/server";
export const FIVEM_ARTIFACT_URL_RE =
  /^https:\/\/runtime\.fivem\.net\/artifacts\/fivem\/build_proot_linux\/master\/(\d{3,6})-([0-9a-f]{40})\/fx\.tar\.xz$/;

/**
 * Render server.cfg. Secrets are NOT in this file: the licence key, RCON
 * password and players token live in `secrets.cfg` (mode 0600, see
 * renderSecretsCfg) which this file `exec`s, so a customer sharing their
 * server.cfg on a forum (common) never leaks their key.
 */
export function renderServerCfg(settings: FivemSettings, opts: { planSlots?: number | null } = {}): string {
  const cap = effectiveSlotCap(opts.planSlots ?? null, settings.licenceTier, settings.onesync);
  const maxClients = Math.max(1, Math.min(settings.sv_maxclients, cap));
  // `resources` holds the customer's EXTRA resources (beyond the defaults every
  // playable server needs); a bad list falls back to the defaults alone rather
  // than writing a broken cfg (validateConfig rejects bad names before this).
  const res = parseResourceList(settings.resources);
  const resources = [...new Set([...FIVEM_DEFAULT_RESOURCES, ...(res.ok ? res.names : [])])];
  const tags = parseTags(settings.tags);
  const lines: string[] = [
    "# Generated by Nxeon from your server Settings — edits here are overwritten when settings are saved.",
    "# Put your own extra config in custom.cfg (exec'd at the end, never overwritten).",
    `endpoint_add_tcp "0.0.0.0:${FIVEM_GAME_PORT}"`,
    `endpoint_add_udp "0.0.0.0:${FIVEM_GAME_PORT}"`,
    "",
    ...resources.map((r) => `ensure ${r}`),
    "",
    `sv_hostname ${cfgQuote(settings.sv_hostname || FIVEM_DEFAULTS.sv_hostname)}`,
    ...(settings.projectName ? [`sets sv_projectName ${cfgQuote(settings.projectName)}`] : []),
    ...(settings.projectDesc ? [`sets sv_projectDesc ${cfgQuote(settings.projectDesc)}`] : []),
    `sets locale ${cfgQuote(settings.locale)}`,
    ...(tags.length ? [`sets tags ${cfgQuote(tags.join(", "))}`] : []),
    `sv_maxclients ${maxClients}`,
    `set onesync ${settings.onesync}`,
    ...(settings.gameBuild ? [`sv_enforceGameBuild ${settings.gameBuild}`] : []),
    ...(settings.sv_password ? [`sv_password ${cfgQuote(settings.sv_password)}`] : []),
    `set steam_webApiKey ${cfgQuote(settings.steamWebApiKey || "none")}`,
    "sv_scriptHookAllowed 0",
    // Keep the public HTTP endpoints answering server browsers + our probe, but
    // never hand player names/identifiers to anonymous callers — FXServer only
    // returns them on /players.json with the token from secrets.cfg.
    "set sv_requestParanoia 0",
    "",
    "exec secrets.cfg",
    "exec custom.cfg",
    "",
  ];
  return lines.join("\n");
}

/** The 0600 secrets file. Values are allowlisted before they get here. */
export function renderSecretsCfg(secrets: { licenseKey: string | null; rconPassword: string; playersToken: string }): string {
  const lines = ["# Nxeon-managed secrets — do not share this file."];
  if (secrets.licenseKey && isValidLicenseKey(secrets.licenseKey)) lines.push(`sv_licenseKey "${secrets.licenseKey}"`);
  if (/^[A-Za-z0-9]{12,64}$/.test(secrets.rconPassword)) lines.push(`rcon_password "${secrets.rconPassword}"`);
  if (/^[A-Za-z0-9]{16,64}$/.test(secrets.playersToken)) lines.push(`set sv_playersToken "${secrets.playersToken}"`);
  return lines.join("\n") + "\n";
}

/**
 * The runtime env file the container's start script sources. Only integers
 * and fixed tokens — nothing customer-typed reaches it.
 */
export function renderRuntimeEnv(settings: FivemSettings, opts: { planSlots?: number | null } = {}): string {
  const cap = effectiveSlotCap(opts.planSlots ?? null, settings.licenceTier, settings.onesync);
  return [
    `NX_TXADMIN=${settings.txadmin ? "1" : "0"}`,
    `TXHOST_MAX_SLOTS=${cap}`,
    "",
  ].join("\n");
}

