/** Every sellable family (has active plans), in catalogue order, with its
 *  tiers' from-price / max slots — one query. */
export async function sellableGames() {
  const rows = await db.gamePlan.findMany({
    where: { active: true },
    select: { gameFamily: true, priceCents: true, introPriceCents: true, introTermMonths: true, termMonths: true, slots: true, ramMB: true, id: true, featured: true },
  });
  const by = new Map<string, typeof rows>();
  for (const r of rows) by.set(r.gameFamily, [...(by.get(r.gameFamily) ?? []), r]);
  return GAME_FAMILIES.filter((f) => by.has(f)).map((f) => {
    const ts = by.get(f)!;
    const monthly = ts.map((t) => {
      const intro = planIntroMonthlyCents(t);
      return (intro ?? t.priceCents) / (t.termMonths > 1 ? t.termMonths : 1);
    });
    const slots = ts.map((t) => t.slots).filter((s): s is number => s != null);
    const standing = ts.map((t) => t.priceCents / (t.termMonths > 1 ? t.termMonths : 1));
    return {
      family: f as string, name: gameName(f), genres: gameGenres(f), route: gameRoute(f),
      fromCents: Math.round(Math.min(...monthly)),
      /** standing monthly price (what renewals charge) — SEO text quotes this, never the intro rate */
      standingCents: Math.round(Math.min(...standing)), maxSlots: slots.length ? Math.max(...slots) : null, tiers: ts.length,
    };
  });
}
export type SellableGame = Awaited<ReturnType<typeof sellableGames>>[number];

