// Player capacity: how Nxeon talks about player counts, everywhere.
//
// Pure and client-safe (no DB, no server-only imports), so the deploy wizard, the
// customer portal, the marketing loaders, emails/invoices and the AI chat agent
// all read the SAME facts from here instead of copy-pasting numbers.
//
// ─── THE POLICY ───────────────────────────────────────────────────────────────
// Nxeon sells game servers by RESOURCES (RAM / vCPU / NVMe), not by player
// slots. Nothing in the platform caps players to a plan: GamePlan.slots is only
// what a tier is SIZED for, and the server's own "Max players" setting (which
// the customer controls in Settings) is what limits joins. So:
//
//   - games with no engine limit       → "Unlimited players"
//   - games with a hard engine limit   → "No player cap from us · up to N, the
//                                          game's own maximum"
//   - games with an official/supported  → "No player cap from us · the game
//     limit that is soft or unverified     officially supports N"
//   - games we could not verify         → "No player cap from us"
//
// and, in smaller muted text, a RECOMMENDED player count derived from the plan's
// RAM + vCPU (recommendedPlayers below). Never claim "unlimited" for a game whose
// own server can't do it, and never present the recommendation as a limit.
//
// ─── THE RECOMMENDATION FORMULA ───────────────────────────────────────────────
// recommendedPlayers(family, {ramMB, cpuCores}) is the exact INVERSE of the
// deploy wizard's "how many players?" slider (lib/game-player-recommend.ts
// recommendedSpecForPlayers, a per-game least-squares fit of the real GamePlan
// tiers): the largest player count whose recommended RAM AND vCPU both fit in
// the plan. Then, conservatively:
//   1. capped at the game's hard maximum (kind "hard") — never recommend more
//      than the game can hold;
//   2. rounded DOWN to a friendly number (exact below 20, multiples of 5 to 100,
//      multiples of 10 above) since it is shown as "~N";
//   3. floored at 1.
// Shown as "Recommended up to ~N for smooth performance on this plan". Heavy
// mods/plugins and big worlds need more; the customer can still set any number.

import type { GameFamily } from "./games";
import { GAME_DISPLAY } from "./games";
import { recommendedSpecForPlayers } from "./game-player-recommend";

export type PlayerCapKind = "unlimited" | "hard" | "official" | "unverified";

export type GamePlayerLimit = {
  kind: PlayerCapKind;
  /** hard: the game's own maximum. official: the officially supported count. */
  max?: number;
  /** Can the server owner change the player limit (config key / launch arg)? */
  configurable: boolean;
  /** One line, shown to staff / used by the AI agent; customer-safe. */
  note: string;
  /** Where the number comes from. */
  source: string;
  confidence: "high" | "medium" | "low";
};

/**
 * Per-game player limits. Researched 2026-10-06 (official docs/wikis where they
 * exist; dedicated-server config docs otherwise) and cross-checked against the
 * caps the game-config Settings fields already enforce (lib/game-config.ts,
 * several of which were verified on real servers by the 2026-09 catalog sweep).
 * "low" confidence rows are deliberately NOT claimed as unlimited.
 */
export const GAME_PLAYER_LIMITS: Record<GameFamily, GamePlayerLimit> = {
  minecraft: { kind: "unlimited", configurable: true, confidence: "high", note: "server.properties max-players accepts any number; hardware is the only limit.", source: "https://minecraft.wiki/w/Server.properties" },
  bedrock: { kind: "unlimited", configurable: true, confidence: "medium", note: "server.properties max-players accepts any integer; default 10.", source: "https://minecraft.wiki/w/Bedrock_Dedicated_Server" },
  rust: { kind: "unlimited", configurable: true, confidence: "medium", note: "server.maxplayers has no engine ceiling; big servers run hundreds.", source: "https://wiki.facepunch.com/rust/Creating-a-server" },
  factorio: { kind: "unlimited", configurable: true, confidence: "high", note: "max_players 0 means unlimited in server-settings.json.", source: "https://wiki.factorio.com/Multiplayer" },
  vintagestory: { kind: "unlimited", configurable: true, confidence: "medium", note: "serverconfig.json MaxClients has no documented ceiling.", source: "https://wiki.vintagestory.at/Server_Config" },
  valheim: { kind: "hard", max: 10, configurable: false, confidence: "high", note: "The dedicated server is hard-coded to 10 players (mods can raise it).", source: "https://valheim.fandom.com/wiki/Dedicated_servers" },
  palworld: { kind: "hard", max: 32, configurable: true, confidence: "high", note: "ServerPlayerMaxNum accepts up to 32.", source: "https://docs.palworldgame.com/settings-and-operation/configuration" },
  cs2: { kind: "hard", max: 64, configurable: true, confidence: "medium", note: "-maxplayers up to 64.", source: "https://developer.valvesoftware.com/wiki/Counter-Strike_2/Dedicated_Servers" },
  terraria: { kind: "hard", max: 255, configurable: true, confidence: "high", note: "maxplayers 1-255 (TShock reserves some slots).", source: "https://terraria.wiki.gg/wiki/Server" },
  ark: { kind: "official", max: 70, configurable: true, confidence: "medium", note: "Official servers run 70; private servers can set MaxPlayers higher.", source: "https://ark.wiki.gg/wiki/Server_configuration" },
  arkasa: { kind: "official", max: 70, configurable: true, confidence: "medium", note: "Official servers run 70 (-WinLiveMaxPlayers).", source: "https://ark.wiki.gg/wiki/Server_configuration" },
  satisfactory: { kind: "official", max: 4, configurable: true, confidence: "medium", note: "Ships with 4; MaxPlayers in Game.ini can be raised (8-16 is common), not officially supported above 4.", source: "https://satisfactory.wiki.gg/wiki/Dedicated_servers" },
  projectzomboid: { kind: "hard", max: 100, configurable: true, confidence: "medium", note: "MaxPlayers accepts up to 100; above ~32 map streaming can suffer.", source: "https://pzwiki.net/wiki/Server_settings" },
  sdtd: { kind: "official", max: 8, configurable: true, confidence: "medium", note: "8 is officially supported; ServerMaxPlayerCount can go higher (saves get risky past ~30).", source: "https://7daystodie.fandom.com/wiki/Server" },
  vrising: { kind: "official", max: 40, configurable: true, confidence: "medium", note: "Stunlock recommends up to 40; MaxConnectedUsers can be set higher.", source: "https://github.com/StunlockStudios/vrising-dedicated-server-instructions" },
  enshrouded: { kind: "hard", max: 16, configurable: true, confidence: "high", note: "slotCount up to 16.", source: "https://enshrouded.fandom.com/wiki/Dedicated_Server" },
  gmod: { kind: "hard", max: 128, configurable: true, confidence: "high", note: "maxplayers up to 128.", source: "https://wiki.facepunch.com/gmod/Downloading_a_Dedicated_Server" },
  conan: { kind: "hard", max: 70, configurable: true, confidence: "medium", note: "Funcom caps servers at 70.", source: "https://conanexiles.fandom.com/wiki/Server_Configuration" },
  unturned: { kind: "hard", max: 200, configurable: true, confidence: "medium", note: "MaxPlayers range is 1-200 (Commands.dat).", source: "https://unturned-docs.readthedocs.io/en/latest/servers/server-hosting.html" },
  theforest: { kind: "hard", max: 8, configurable: true, confidence: "medium", note: "Co-op cap of 8.", source: "https://theforest.fandom.com/wiki/Dedicated_Servers" },
  sonsoftheforest: { kind: "hard", max: 8, configurable: true, confidence: "medium", note: "Co-op cap of 8.", source: "https://sonsoftheforest.fandom.com/wiki/Dedicated_Server" },
  schedule1: { kind: "unverified", configurable: false, confidence: "low", note: "No official dedicated server (not sold).", source: "lib/game-control.ts" },
  dragonwilds: { kind: "hard", max: 6, configurable: true, confidence: "medium", note: "The game's co-op limit is 6.", source: "https://xgamingserver.com/docs/runescape-dragonwilds/max-players" },
  sunkenland: { kind: "hard", max: 15, configurable: true, confidence: "low", note: "Up to 15 players.", source: "https://ggservers.com/knowledgebase/ (Sunkenland max players)" },
  abioticfactor: { kind: "official", max: 6, configurable: true, confidence: "medium", note: "Designed for 6; MaxServerPlayers can be raised.", source: "https://xgamingserver.com/docs/abiotic-factor" },
  corekeeper: { kind: "official", max: 8, configurable: true, confidence: "medium", note: "Co-op is built around 8; the dedicated-server maxPlayers can be raised.", source: "https://core-keeper.fandom.com/wiki/Server_Config" },
  icarus: { kind: "hard", max: 8, configurable: true, confidence: "medium", note: "Up to 8 players.", source: "https://xgamingserver.com/docs/icarus/player-slots" },
  soulmask: { kind: "official", max: 50, configurable: true, confidence: "low", note: "Documented limit 50; some servers run more.", source: "https://xgamingserver.com/docs/soulmask" },
  dst: { kind: "hard", max: 64, configurable: true, confidence: "medium", note: "max_players up to 64.", source: "https://dontstarve.wiki.gg/wiki/Guides/Don%E2%80%99t_Starve_Together_Dedicated_Servers" },
  necesse: { kind: "hard", max: 250, configurable: true, confidence: "medium", note: "slots up to 250.", source: "https://xgamingserver.com/docs/necesse" },
  tf2: { kind: "hard", max: 100, configurable: true, confidence: "high", note: "-maxplayers up to 100 since TF2's 100-player update.", source: "https://developer.valvesoftware.com/wiki/Team_Fortress_2_Dedicated_Server" },
  l4d2: { kind: "official", max: 8, configurable: true, confidence: "low", note: "4 in co-op, 8 in versus without mods.", source: "https://developer.valvesoftware.com/wiki/Left_4_Dead_2_Dedicated_Server" },
  nightingale: { kind: "official", max: 6, configurable: true, confidence: "medium", note: "6 by default; more is unsupported.", source: "https://supercraft.host/wiki/nightingale" },
  squad: { kind: "hard", max: 100, configurable: true, confidence: "medium", note: "100 players.", source: "https://squad.fandom.com/wiki/Server_Configuration" },
  spaceengineers: { kind: "hard", max: 64, configurable: true, confidence: "medium", note: "Up to 64 players.", source: "https://xgamingserver.com/docs/space-engineers/max-players" },
  kf2: { kind: "hard", max: 6, configurable: true, confidence: "medium", note: "Survival is 6 players (12 in Versus).", source: "https://xgamingserver.com/docs/killing-floor-2/configure-your-server" },
  barotrauma: { kind: "official", max: 16, configurable: true, confidence: "low", note: "Crews are designed for up to 16.", source: "https://xgamingserver.com/docs/barotrauma/max-players" },
  sandstorm: { kind: "official", max: 28, configurable: true, confidence: "low", note: "Versus is designed for 28 (14v14), co-op for 8.", source: "https://www.gamehostbros.com/guides/games/insurgency-sandstorm/max-players" },
