  let lo = 0;
  let hi = MAX_SEARCH;
  if (fits(hi)) lo = hi;
  else {
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1;
      if (fits(mid)) lo = mid;
      else hi = mid;
    }
  }
  const hard = gameHardMax(f);
  const capped = hard != null ? Math.min(lo, hard) : lo;
  // A hard max is an exact number; don't round it to a "nicer" smaller one.
  if (hard != null && capped === hard) return hard;
  return friendlyPlayers(Math.max(1, capped));
}

/** Short headline for a game: what the big text says. */
export function playerCapHeadline(family: string | null | undefined): string {
  const l = playerLimitFor(family);
  if (l.kind === "unlimited") return "Unlimited players";
  if (l.kind === "hard" && l.max) return `Up to ${l.max} players`;
  return "No player cap from us";
}

/** One sentence explaining the cap (or lack of one). Customer-facing. */
export function playerCapDetail(family: string | null | undefined): string {
  const l = playerLimitFor(family);
  const name = GAME_DISPLAY[family as GameFamily]?.name ?? "This game";
  if (l.kind === "unlimited") return "No player cap from us — set any max players in Settings.";
  if (l.kind === "hard" && l.max) return `No player cap from us — up to ${l.max}, ${name}'s own maximum.`;
  if (l.kind === "official" && l.max) return `No player cap from us — ${name} officially supports ${l.max}.`;
  return "No player cap from us — set your own max players in Settings.";
}

/** The small muted line under the headline, for a specific plan. */
export function recommendedLine(rec: number | null, opts: { short?: boolean } = {}): string | null {
  if (rec == null) return null;
  return opts.short ? `Recommended ~${rec} players` : `Recommended up to ~${rec} for smooth performance on this plan`;
}

export type PlanPlayerInfo = {
  kind: PlayerCapKind;
  /** Big text: "Unlimited players" / "Up to 32 players" / "No player cap from us". */
  headline: string;
  /** Explanation sentence. */
  detail: string;
  /** Plan-specific recommendation, or null when unknown. */
  recommended: number | null;
  /** Small muted text: "Recommended up to ~20 for smooth performance on this plan". */
  recommendedText: string | null;
  /** Compact one-liner for chips/meta: "Unlimited players · ~20 recommended". */
  compact: string;
};

/** Everything a surface needs to present players for one plan. */
export function planPlayerInfo(family: string | null | undefined, spec: { ramMB: number; cpuCores: number } | null): PlanPlayerInfo {
  const l = playerLimitFor(family);
  const recommended = spec ? recommendedPlayers(family, spec) : null;
  const headline = playerCapHeadline(family);
  return {
    kind: l.kind,
    headline,
    detail: playerCapDetail(family),
    recommended,
    recommendedText: recommendedLine(recommended),
    compact: recommended != null ? `${headline} · ~${recommended} recommended` : headline,
  };
}

/** The neutral marketing line (never names anyone else). */
export const NO_SLOT_LIMITS_LINE = "No slot limits. Ever.";

/**
 * Game plan names carry a slot count ("Minecraft — 4 GB / 20 slots"), which reads
 * as a hard cap. Strip it at display time: "Minecraft — 4 GB". Keeps any mode
 * suffix ("Arma Reforger — 6 GB (Skirmish)"). Custom-plan names are unaffected.
 */
export function displayGamePlanName(name: string | null | undefined): string {
  if (!name) return "";
  return name
    .replace(/\s*\/\s*\d+\s*(?:player\s+)?(?:slots?|players?)\b/i, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

/** Recommended-ness of a Settings max-players value, for the Settings help text. */
export function maxPlayersHelp(family: string | null | undefined, rec: number | null): string {
  const l = playerLimitFor(family);
  const name = GAME_DISPLAY[family as GameFamily]?.name ?? "the game";
  const cap =
    l.kind === "hard" && l.max ? ` ${name} itself allows up to ${l.max}.`
    : l.kind === "official" && l.max ? ` ${name} officially supports ${l.max}.`
    : "";
  const r = rec != null ? ` About ${rec} runs smoothly on your current plan; more players need more RAM.` : "";
  return `Nxeon doesn't cap players — this is your server's own limit.${cap}${r}`;
}

/**
 * Plain-text facts for the AI chat agent's knowledge (the chat-agent prompt
 * lives on another branch; import this rather than copying numbers into it).
 */
export function playerPolicyKnowledge(): string {
  const lines = [
    "PLAYER COUNTS (game servers): Nxeon never caps players by plan. Plans are sized by RAM/vCPU/NVMe; the plan's player number is only a RECOMMENDATION for smooth performance, computed from the plan's resources. The server's own Max players setting (customer-editable in Settings) is what limits joins. Some games have their OWN engine maximum, which no host can exceed — say 'no player cap from us, up to N (the game's own maximum)' for those, and only say 'unlimited' for games listed as unlimited below. Never name or disparage other hosts.",
  ];
  const by: Record<PlayerCapKind, string[]> = { unlimited: [], hard: [], official: [], unverified: [] };
  for (const [f, l] of Object.entries(GAME_PLAYER_LIMITS) as [GameFamily, GamePlayerLimit][]) {
    if (f === "schedule1") continue;
    const n = GAME_DISPLAY[f]?.name ?? f;
    by[l.kind].push(l.max ? `${n} (${l.max})` : n);
  }
  lines.push(`Unlimited players (no engine cap): ${by.unlimited.join(", ")}.`);
  lines.push(`Game's own hard maximum: ${by.hard.join(", ")}.`);
  lines.push(`Officially supported count (soft, can be raised in Settings): ${by.official.join(", ")}.`);
  lines.push(`Configurable, maximum not confirmed (say 'no player cap from us'): ${by.unverified.join(", ")}.`);
  return lines.join("\n");
}

