import { test } from "node:test";
import assert from "node:assert/strict";
import { GAME_FAMILIES } from "../lib/games.ts";
import {
  GAME_PLAYER_LIMITS,
  displayGamePlanName,
  friendlyPlayers,
  gameHardMax,
  planPlayerInfo,
  playerCapHeadline,
  playerPolicyKnowledge,
  recommendedPlayers,
} from "../lib/game-player-capacity.ts";
import { GAME_CONFIG_SCHEMAS } from "../lib/game-config.ts";

test("every game family has a player-limit row", () => {
  for (const f of GAME_FAMILIES) assert.ok(GAME_PLAYER_LIMITS[f], `missing limit for ${f}`);
});

test("hard and official rows carry a number; unlimited/unverified rows do not", () => {
  for (const [f, l] of Object.entries(GAME_PLAYER_LIMITS)) {
    if (l.kind === "hard" || l.kind === "official") assert.ok((l.max ?? 0) > 0, `${f}: needs max`);
    else assert.equal(l.max, undefined, `${f}: ${l.kind} must not carry a max`);
    assert.ok(l.source, `${f}: needs a source`);
  }
});

test("'unlimited' is only ever claimed for a game whose row says so, and never with low confidence", () => {
  for (const f of GAME_FAMILIES) {
    const l = GAME_PLAYER_LIMITS[f];
    const h = playerCapHeadline(f);
    if (l.kind === "unlimited") {
      assert.equal(h, "Unlimited players");
      assert.notEqual(l.confidence, "low", `${f}: unlimited needs evidence`);
    } else assert.ok(!/unlimited/i.test(h), `${f}: must not claim unlimited`);
  }
  // Spot checks the owner will be asked about.
  assert.equal(GAME_PLAYER_LIMITS.minecraft.kind, "unlimited");
  assert.equal(gameHardMax("valheim"), 10);
  assert.equal(gameHardMax("palworld"), 32);
  assert.equal(gameHardMax("enshrouded"), 16);
});

test("recommendation never exceeds a game's hard maximum", () => {
  for (const f of GAME_FAMILIES) {
    const hard = gameHardMax(f);
    if (hard == null) continue;
    const r = recommendedPlayers(f, { ramMB: 262144, cpuCores: 64 });
    assert.ok(r != null && r <= hard, `${f}: ${r} > ${hard}`);
  }
  // Valheim's 8 GB tier was sold as "20 players"; the game holds 10.
  assert.equal(recommendedPlayers("valheim", { ramMB: 8192, cpuCores: 3 }), 10);
});

test("recommendation grows (never shrinks) with more resources", () => {
  for (const f of GAME_FAMILIES) {
    let prev = 0;
    for (const [ram, cpu] of [[2048, 1], [4096, 2], [8192, 3], [16384, 6], [32768, 10]]) {
      const r = recommendedPlayers(f, { ramMB: ram, cpuCores: cpu }) ?? 0;
      assert.ok(r >= prev, `${f}: ${r} < ${prev} at ${ram} MB`);
      assert.ok(r >= 1, `${f}: at least 1`);
      prev = r;
    }
  }
});

test("recommendation lands near the slot counts the live tiers were sold for", () => {
  // Real active tiers (GamePlan, 2026-10-06): within ~25% below, never wildly above.
  const cases: [string, number, number, number][] = [
    ["minecraft", 2048, 2, 10], ["minecraft", 4096, 2, 20], ["minecraft", 8192, 3, 50],
    ["rust", 10240, 4, 150], ["palworld", 16384, 4, 32], ["ark", 32768, 6, 100],
    ["enshrouded", 16384, 6, 16], ["squad", 16384, 6, 50], ["vrising", 12288, 4, 80],
  ];
  for (const [f, ram, cpu, sold] of cases) {
    const r = recommendedPlayers(f, { ramMB: ram, cpuCores: cpu })!;
    assert.ok(r >= Math.floor(sold * 0.75) && r <= Math.ceil(sold * 1.1), `${f} ${ram}: rec ${r} vs sold ${sold}`);
  }
});

test("friendlyPlayers rounds down to readable numbers", () => {
  assert.equal(friendlyPlayers(7), 7);
  assert.equal(friendlyPlayers(19), 19);
  assert.equal(friendlyPlayers(22), 20);
  assert.equal(friendlyPlayers(48), 45);
  assert.equal(friendlyPlayers(149), 140);
  assert.equal(friendlyPlayers(0), 1);
});

test("planPlayerInfo wording", () => {
  const mc = planPlayerInfo("minecraft", { ramMB: 4096, cpuCores: 2 });
  assert.equal(mc.headline, "Unlimited players");
  assert.equal(mc.recommendedText, "Recommended up to ~20 for smooth performance on this plan");
  assert.equal(mc.compact, "Unlimited players · ~20 recommended");
  const vh = planPlayerInfo("valheim", { ramMB: 4096, cpuCores: 2 });
  assert.equal(vh.headline, "No player cap from us");
  assert.equal(vh.gameLimit, "Up to 10 players, the game's own maximum");
  assert.match(vh.detail, /up to 10, Valheim's own maximum/);
  assert.equal(planPlayerInfo("nope", null).recommended, null);
});

test("displayGamePlanName strips the slot count, keeps everything else", () => {
  assert.equal(displayGamePlanName("Minecraft — 4 GB / 20 slots"), "Minecraft — 4 GB");
  assert.equal(displayGamePlanName("Valheim — 8 GB / 20 players"), "Valheim — 8 GB");
  assert.equal(displayGamePlanName("Arma Reforger — 6 GB / 16 players (Skirmish)"), "Arma Reforger — 6 GB (Skirmish)");
  assert.equal(displayGamePlanName("CS2 — 4 GB / 24 slots (custom, +30GB disk correction)"), "CS2 — 4 GB (custom, +30GB disk correction)");
  assert.equal(displayGamePlanName("Custom 6 vCPU / 23 GB / 124 GB Disk (minecraft)"), "Custom 6 vCPU / 23 GB / 124 GB Disk (minecraft)");
  assert.equal(displayGamePlanName(null), "");
});

