    if (!field) continue;
    assert.ok((field.max ?? 0) >= hard, `${f}: Settings max ${field.max} is below the game's ${hard}`);
  }
});

test("unlimited games' Settings max-players does not impose a low ceiling", () => {
  for (const f of GAME_FAMILIES) {
    if (GAME_PLAYER_LIMITS[f].kind !== "unlimited") continue;
    const schema = (GAME_CONFIG_SCHEMAS as Record<string, { fields: { label: string; type: string; max?: number }[] }>)[f];
    const field = schema?.fields.find((x) => x.type === "int" && /^max ?players$/i.test(x.label));
    if (field) assert.ok((field.max ?? 0) >= 1000, `${f}: Settings max ${field.max} reads as a cap`);
  }
});

test("AI knowledge text covers the policy and never names another host", () => {
  const k = playerPolicyKnowledge();
  assert.match(k, /never caps players/);
  assert.match(k, /Valheim \(10\)/);
  assert.match(k, /Minecraft/);
});

