/** A tier's display name without a trailing "/ N slots" — several seeded tier
 *  names carry one ("Minecraft — 2 GB / 10 slots"), which reads as a hard
 *  player cap. The card already states the count as a recommendation. */
function tierLabel(name: string): string {
  return name.replace(/\s*\/\s*\d+\s*(player\s*)?slots?\b/i, "").trim();
}

/** Largest player count any of this family's sellable tiers provides. */
function maxSlots(g: GameFamilyOption): number | null {
  const counts = g.tiers.map((t) => t.slots).filter((n): n is number => typeof n === "number" && n > 0);
  return counts.length ? Math.max(...counts) : null;
}

/* One game-picker card. Split out from an inline `.map()` body so each tile
 * can hold its OWN "did the image actually load" state — `onError` hiding a
 * failed <img> is the same convention already used for this same hero art in
