 * wizard's grid was the one surface still rendering a bare <img src={g.art}>
 * with nothing to catch a 404 (kf2 has cover art but no hero shot yet — that
 * shows here as a broken-image glyph instead of the service-mark fallback
 * every OTHER artless family already gets). */
function GameTile({ g, on, onClick }: { g: GameFamilyOption; on: boolean; onClick: () => void }) {
  const money = useMoney();
  const [imgOk, setImgOk] = useState(true);
  const showArt = g.art && imgOk;
  return (
    <Pick on={on} onClick={onClick} className="group flex flex-col gap-1.5 p-1.5">
      <span className="relative block aspect-[4/3] w-full overflow-hidden rounded-[7px]">
        {g.popular && (
          /* Solid, not the translucent-tint treatment "First month free" uses
             elsewhere — that one sits on a plain dark card, this one sits on
             top of an arbitrary, often bright game screenshot. A ~16%-alpha
             mint tint over a busy photo has no reliable contrast against it;
             a near-opaque dark chip does, regardless of what's underneath. */
          <span className="absolute left-1.5 top-1.5 z-[1] rounded-full border border-[rgba(17,200,142,0.5)]
                           bg-[#04140f]/90 px-1.5 py-[2px] text-[9px] font-bold uppercase
                           tracking-[0.03em] text-mint">
            Popular
          </span>
        )}
        {showArt ? (
          <img src={g.art!} alt="" loading="lazy" draggable={false} onError={() => setImgOk(false)}
               className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.07]"
               style={{ WebkitMaskImage: "linear-gradient(180deg,#000 66%,transparent 100%)",
                        maskImage: "linear-gradient(180deg,#000 66%,transparent 100%)" }} />
        ) : (
          /* No artwork for this family — the service mark rather than
             a broken image or an empty box. */
          <span className="grid h-full w-full place-items-center bg-well">
            <SvcIcon name="game" size={54} />
          </span>
        )}
      </span>
      <span className="flex items-center gap-1.5 px-1">
        <Icon name="flame" size={15} className="flex-none"
              style={{ filter: "hue-rotate(240deg) saturate(1.05) brightness(0.98)" }} />
        <span className="trunc text-[12.5px] font-semibold text-white">{g.name}</span>
      </span>
