 */
export function configuredMaxPlayers(family: string | null | undefined, gameConfig: unknown): number | null {
  const f = maxPlayersField(family);
  if (!f) return null;
  const raw = gameConfig && typeof gameConfig === "object" ? (gameConfig as Record<string, unknown>)[f.key] : undefined;
  const n = Math.trunc(Number(raw ?? f.default));
  return Number.isFinite(n) && n > 0 ? n : null;
}

