 * (lib/game-player-capacity.ts displayGamePlanName). `slots` (the tier's
 * recommended count) is only the fallback when there is no name at all.
 */
export function gamePlanSpecs(planName: string | undefined, gameName: string | null, slots: number | null | undefined): string | null {
  const fallback = slots ? `~${slots} players recommended` : null;
