export async function realTiers(family: string, regions: string[]): Promise<RealTier[]> {
  return (await tiersByFamily(regions, family)).get(family) ?? [];
}

/** Active tiers grouped by family (one query), cheapest first. */
export async function tiersByFamily(regions: string[], family?: string): Promise<Map<string, RealTier[]>> {
  const rows = await db.gamePlan.findMany({
    where: { active: true, ...(family ? { gameFamily: family } : {}) },
    orderBy: [{ ramMB: "asc" }, { sortOrder: "asc" }],
  });
  const out = new Map<string, RealTier[]>();
  for (const g of rows) out.set(g.gameFamily, [...(out.get(g.gameFamily) ?? []), toTier(g, regions)]);
  return out;
}

